# f08 城塞の攻防 - 目的が左右で違う非対称マップ。
# 守備側(陣営0)は山に囲まれた城塞に少数で籠もる。**40ターン耐えれば守備側の勝ち**
# （timeout_winner=0）。攻撃側(陣営1)は数で押し、**拠点を10個確保すれば勝ち**
# （objective_count=10 / objective_player=1）。
# 拠点は全部で16個あり、守備側は最初から8個持っている。
# 攻撃側は守備側の拠点を半分以上剥がさないと届かない計算。
# 対称ではない。左右で戦力も資金も目的も違う。
[map]
name             = 城塞の攻防
width            = 42
height           = 28
turns            = 40
timeout_winner   = 0
objective_count  = 10
objective_player = 1
funds0           = 2200
funds1           = 5000

